# Logos for stations that have no TMDB company ID, keyed by station key.
# Updated by dev/update_logos.py.
DIRECT_LOGOS = {
    'netzkino': "",
}


def get_logo(yolo_name):
    """Return base64-encoded PNG logo for a YOLO station name, or None."""
    tmdb_id = YOLO_TO_TMDB.get(yolo_name)
    if tmdb_id is not None:
        logo = TMDB_LOGOS.get(tmdb_id)
        if logo:
            return logo
    return DIRECT_LOGOS.get(yolo_name)


def process_logo(img_bytes):
    """Convert raw image bytes to a grayscale alpha-preserving PNG, resized to fit _LOGO_MAX_W x _LOGO_MAX_H."""
    img = Image.open(io.BytesIO(img_bytes)).convert("RGBA")
    img.thumbnail((_LOGO_MAX_W, _LOGO_MAX_H), Image.Resampling.LANCZOS)
    r, g, b, a = img.split()
    gray = Image.merge("RGB", (r, g, b)).convert("L")
    result = Image.merge("LA", (gray, a))
    out = io.BytesIO()
    result.save(out, format="PNG", optimize=True)
    return base64.b64encode(out.getvalue()).decode("ascii")


def detect_tvstation_from_filename(filename):
    """Return station key if a {Tag} in the filename matches a known station in YOLO_DISPLAY_NAMES, else None."""
    m = re.search(r'\b(\d{4})\b.*?\{(.*?)\}', filename)
    if not m:
        return None
    tag = m.group(2).lower()
    return tag if tag in YOLO_DISPLAY_NAMES else None


def load_model(model_path=None):
    try:
        from ultralytics import YOLO
    except ImportError:
        return None
    path = model_path or _DEFAULT_MODEL
    if not os.path.isfile(path):
        return None
    return YOLO(path)


def detect_tvstation(model, screenshot_bytes, min_confidence=0.5):
    if not screenshot_bytes:
        return None
    img = Image.open(io.BytesIO(bytes(screenshot_bytes)))
    results = model.predict(img, verbose=False)
    if not results:
        return None
    boxes = results[0].boxes
    if boxes is None or len(boxes) == 0:
        return None
    best_idx = int(boxes.conf.argmax())
    if float(boxes.conf[best_idx]) < min_confidence:
        return None
    cls_id = int(boxes.cls[best_idx])
    return results[0].names[cls_id]


def backfill_tvstation(db, model):
    from . import database
    from collections import Counter
    cur = db.cursor()
    cur.execute("SELECT id, filename FROM files WHERE tvstation IS NULL")
    file_rows = cur.fetchall()
    for file_row in file_rows:
        file_id = file_row["id"]
        filename = file_row["filename"]
        station = detect_tvstation_from_filename(filename)
        if station is not None:
            db.cursor().execute("UPDATE files SET tvstation = ? WHERE id = ?", (station, file_id))
            verbose(f"{filename} :: {station} (filename)", 2)
            continue
        if model is None:
            verbose(f"{filename} :: ---", 2)
            continue
        attachments = database.get_file_attachments(db, file_id, 'screenshot')
        if not attachments:
            continue
        detections = []
        for att in attachments:
            result = detect_tvstation(model, bytes(att["data"]))
            if result is not None:
                detections.append(result)
        if detections:
            station = Counter(detections).most_common(1)[0][0]
            db.cursor().execute("UPDATE files SET tvstation = ? WHERE id = ?", (station, file_id))
            verbose(f"{filename} :: {'/'.join(str(item) for item in detections)}", 2)
        else:
            verbose(f"{filename} :: ---", 2)
    db.commit()


def clear_tvstation(db):
    db.cursor().execute("UPDATE files SET tvstation = NULL")
    db.commit()
